/* 关键词匹配，返回按匹配强度排序的知识点（最多 limit 个） */
function matchKnowledge(text, limit) {
  var scored = [];
  for (var i = 0; i < KP_KEYWORDS.length; i++) {
    var entry = KP_KEYWORDS[i];
    var score = 0;
    for (var j = 0; j < entry.re.length; j++) {
      if (entry.re[j].test(text)) score++;
    }
    if (score > 0) scored.push({ id: entry.id, score: score });
  }
  scored.sort(function(a, b){ return b.score - a.score; });
  var out = [];
  for (var k = 0; k < scored.length && out.length < (limit || 2); k++) {
    var kp = KP_BY_ID[scored[k].id];
    if (kp) out.push(kp);
  }
  return out;
}

/* 主入口：给定卷代码 + 题目对象，返回应考察的【最小知识点】数组
   优先查原子考点标注表（Q_ATOM / ATOM_KB）；未标注的题（用户导入）回退到关键词匹配。
   返回对象保留 point / need / approach / pitfall，供错题剖析与归纳总结直接使用。*/
function knowledgeFor(code, q) {
  var key = code + "-" + q.num;
  if (typeof Q_ATOM !== "undefined" && typeof ATOM_KB !== "undefined" && Q_ATOM[key]) {
    var atomId = Q_ATOM[key];
    var meta = ATOM_KB[atomId];
    if (meta) {
      var base = KP_BY_ID[meta.kpId] || KP_BY_ID["general"] || KP_KB[0];
      var fineKp = meta.fine ? KP_BY_ID[atomId] : null;
      var related = [];
      if (KP_OVERRIDE[key]) {
        KP_OVERRIDE[key].slice(1).forEach(function(rid){
          if (KP_BY_ID[rid]) related.push(KP_BY_ID[rid].name);
        });
      }
      return [{
        id: atomId, atomId: atomId, name: meta.name,
        chapter: meta.chapter, chapterId: meta.chapterId, subject: meta.subject,
        legacyId: (typeof Q_LEGACY !== "undefined" && Q_LEGACY[key]) || meta.chapterId,
        point: fineKp ? fineKp.point :
          ("这组错题考的都是最小知识点「" + meta.name + "」，属于「" + meta.chapter +
           "」。下面是该章节通用的知识储备与解题步骤，做题时先按最小知识点选方法。"),
        need: (fineKp ? fineKp.need : base.need).slice(),
        approach: (fineKp ? fineKp.approach : base.approach).slice(),
        pitfall: fineKp ? fineKp.pitfall : base.pitfall,
        fine: !!meta.fine, related: related
      }];
    }
  }
  if (q && q.kpId && KP_BY_ID[q.kpId]) return [KP_BY_ID[q.kpId]];
  if (KP_OVERRIDE[key]) {
    var arr = [];
    KP_OVERRIDE[key].forEach(function(id){
      if (KP_BY_ID[id]) arr.push(KP_BY_ID[id]);
    });
    if (arr.length) return arr;
  }
  var parts = [q.question || ""];
  if (q.options) {
    Object.keys(q.options).forEach(function(l){ parts.push(q.options[l] || ""); });
  }
  if (q.explanation) parts.push(q.explanation);
  var matched = matchKnowledge(parts.join(" "), 2);
  if (matched.length) return matched;
  return KP_BY_ID["general"] ? [KP_BY_ID["general"]] : [];
}

