/* 惰性构建：调用时 KP_VARIANTS 一定已加载，避免脚本顺序依赖 */
var _atomVariantsCache = null;
function atomVariants(){
  if (_atomVariantsCache) return _atomVariantsCache;
  var m = {};
  Object.keys(V_ATOM || {}).forEach(function(k){
    var p = k.split("#");
    var arr = (typeof KP_VARIANTS !== "undefined" && KP_VARIANTS[p[0]]) || [];
    var v = arr[Number(p[1])];
    if (!v) return;
    var id = V_ATOM[k];
    if (!m[id]) m[id] = [];
    m[id].push({ q: v.q, options: v.options, answer: v.answer,
      solution: (v.solution || []).slice(), source: "手写变式", atomId: id });
  });
  _atomVariantsCache = m;
  return m;
}

function atomMeta(id){ return ATOM_KB[id] || null; }
function atomName(id){ return (ATOM_KB[id] && ATOM_KB[id].name) || "综合"; }
function atomOf(code, num){ return Q_ATOM[code + "-" + num] || null; }
function legacyOf(code, num){ return Q_LEGACY[code + "-" + num] || null; }

